import json

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        res = {}
        all_keys = set(a.keys()) | set(b.keys())
        for k in all_keys:
            if k in a and k in b:
                res[k] = deep_merge(a[k], b[k])
            elif k in a:
                res[k] = a[k]
            else:
                res[k] = b[k]
        return res
    elif isinstance(a, list) and isinstance(b, list):
        res = []
        for item in a + b:
            if item not in res:
                res.append(item)
        return res
    else:
        return b

