import Foundation

let filePath = "/tmp/…/employees.csv"

func runReport() {
    guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
        return
    }

    let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }
    if lines.isEmpty { return }

    let dataLines = lines.dropFirst()

    struct Employee {
        let name: String
        let department: String
        let salary: Double
    }

    var employees: [Employee] = []
    for line in dataLines {
        let cols = line.components(separatedBy: ",")
        if cols.count >= 4 {
            let name = cols[1].trimmingCharacters(in: .whitespaces)
            let dept = cols[2].trimmingCharacters(in: .whitespaces)
            let salary = Double(cols[3].trimmingCharacters(in: .whitespaces)) ?? 0
            employees.append(Employee(name: name, department: dept, salary: salary))
        }
    }

    var deptSalaries: [String: (sum: Double, count: Int)] = [:]
    var totalBudget: Double = 0
    var highestPaid: Employee? = nil

    for emp in employees {
        deptSalaries[emp.department, default: (0, 0)].sum += emp.salary
        deptSalaries[emp.department, default: (0, 0)].count += 1
        totalBudget += emp.salary
        if highestPaid == nil || emp.salary > highestPaid!.salary {
            highestPaid = emp
        }
    }

    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","

    func formatValue(_ value: Double, decimals: Int) -> String {
        formatter.minimumFractionDigits = decimals
        formatter.maximumFractionDigits = decimals
        return formatter.string(from: NSNumber(value: value)) ?? "0"
    }

    print("=== Salary Report ===\n")

    print("Average Salary by Department:")
    let sortedDepts = deptSalaries.keys.sorted()
    for dept in sortedDepts {
        let stats = deptSalaries[dept]!
        let avg = stats.sum / Double(stats.count)
        print("  \(dept): $\(formatValue(avg, decimals: 2))")
    }

    print("\nHighest Paid: \(highestPaid?.name ?? "") ($\(formatValue(highestPaid?.salary ?? 0, decimals: 0)))")

    print("\nDepartments with >2 employees:")
    let largeDepts = sortedDepts.filter { deptSalaries[$0]!.count > 2 }
    for dept in largeDepts {
        print("  \(dept) (\(deptSalaries[dept]!.count) employees)")
    }

    print("\nTotal Budget: $\(formatValue(totalBudget, decimals: 0))")
}

