                String name = cols[1].trim();
                String dept = cols[2].trim();
                double salary = Double.parseDouble(cols[3].trim());

                deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
                totalBudget += salary;

                if (salary > maxSalary) {
                    maxSalary = salary;
                    maxSalaryName = name;
                }
            }
        } catch (IOException e) {
            // Handle potential IO errors
        }

