import * as fs from 'fs';

/**
 * Helper to determine if a value is a plain object (not null, not array).
 */
function isObject(val: any): boolean {
    return val !== null && typeof val === 'object' && !Array.isArray(val);
}

/**
 * Deep merges two values based on the specified rules.
 */
function deepMerge(a: any, b: any): any {
    // If both values are arrays: concatenate and remove duplicates
    if (Array.isArray(a) && Array.isArray(b)) {
        const result: any[] = [];
        const seen = new Set();

        [...a, ...b].forEach(item => {
            // Use JSON.stringify to handle deep equality for objects/arrays in the set
            const identifier = (isObject(item) || Array.isArray(item)) 
                ? JSON.stringify(item) 
                : item;
            if (!seen.has(identifier)) {
                seen.add(identifier);
                result.push(item);
            }
        });
        return result;
    }

    // If both values are objects: merge recursively
    if (isObject(a) && isObject(b)) {
        const result: any = { ...a };
        for (const key in b) {
            if (Object.prototype.hasOwnProperty.call(b, key)) {
                if (Object.prototype.hasOwnProperty.call(a, key)) {
                    result[key] = deepMerge(a[key], b[key]);
                } else {
                    result[key] = b[key];
                }
            }
        }
        return result;
    }

    // Scalar conflict: value from B overrides A
    return b;
}

/**
 * Recursively sorts object keys alphabetically.
 */
function sortObject(obj: any): any {
    if (Array.isArray(obj)) {
        return obj.map(sortObject);
    }
    if (isObject(obj)) {
        const sorted: any = {};
        const keys = Object.keys(obj).sort();
        for (const key of keys) {
            sorted[key] = sortObject(obj[key]);
        }
        return sorted;
    }
    return obj;
}

