import * as fs from 'fs';

function analyzeLogs() {
    const filePath = '/tmp/…/app.log';
    let content = '';
    try {
        content = fs.readFileSync(filePath, 'utf8');
    } catch (e) {
        return;
    }

    const lines = content.split(/\r?\n/);
    const levelCounts = new Map<string, number>();
    const componentErrors = new Map<string, number>();
    const uniqueErrors = new Set<string>();
    const hourCounts = new Map<string, number>();

    // Regex captures: 1: hour, 2: level, 3: component, 4: message
    const regex = /^\[\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\] (\w+) \(([^)]+)\) - (.*)$/;

    for (const line of lines) {
        if (!line.trim()) continue;
        const match = line.match(regex);
        if (!match) continue;

        const [, hour, level, component, message] = match;

        levelCounts.set(level, (levelCounts.get(level) || 0) + 1);
        hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);

        if (level === 'ERROR') {
            componentErrors.set(component, (componentErrors.get(component) || 0) + 1);
            uniqueErrors.add(message);
        }
    }

    process.stdout.write('=== Log Analysis ===\n\n');

    process.stdout.write('Entries by Level:\n');
    const sortedLevels = Array.from(levelCounts.keys()).sort();
    for (const level of sortedLevels) {
        process.stdout.write(`  ${level}: ${levelCounts.get(level)}\n`);
    }

    process.stdout.write('\n');

    let mostErrorComponent = '';
    let maxErrorCount = 0;
    for (const [comp, count] of componentErrors) {
        if (count > maxErrorCount) {
            maxErrorCount = count;
            mostErrorComponent = comp;
        }
    }
    process.stdout.write(`Component with Most Errors: ${mostErrorComponent} (${maxErrorCount} errors)\n`);

    process.stdout.write('\n');

    process.stdout.write('Unique Error Messages:\n');
    const sortedErrors = Array.from(uniqueErrors).sort();
    for (const err of sortedErrors) {
        process.stdout.write(`  - ${err}\n`);
    }

    process.stdout.write('\n');

    let busiestHour = '';
    let maxHourCount = 0;
    for (const [hour, count] of hourCounts) {
        if (count > maxHourCount) {
            maxHourCount = count;
            busiestHour = hour;
        }
    }
    process.stdout.write(`Busiest Hour: ${busiestHour}:00 (${maxHourCount} entries)\n`);
}

