import * as fs from 'fs';

/**
 * This program reads an employees CSV file and produces a salary report
 * with specific formatting requirements.
 */
function generateSalaryReport() {
    const filePath = '/tmp/…/employees.csv';

    try {
        const data = fs.readFileSync(filePath, 'utf8');
        const lines = data.trim().split(/\r?\n/);
        if (lines.length === 0) return;

        // Simple CSV parser to handle basic comma separation
        const employees = lines.slice(1).map(line => {
            const values = line.split(',');
            return {
                name: values[1]?.trim().replace(/"/g, '') || '',
                department: values[2]?.trim().replace(/"/g, '') || '',
                salary: parseFloat(values[3]?.trim().replace(/"/g, '').replace(/\$/g, '').replace(/,/g, '') || '0'),
            };
        });

        const deptStats: { [key: string]: { sum: number, count: number } } = {};
        let totalBudget = 0;
        let highestPaidName = '';
        let highestPaidSalary = -Infinity;

        employees.forEach(emp => {
            if (!deptStats[emp.department]) {
                deptStats[emp.department] = { sum: 0, count: 0 };
            }
            deptStats[emp.department].sum += emp.salary;
            deptStats[emp.department].count += 1;
            totalBudget += emp.salary;

            if (emp.salary > highestPaidSalary) {
                highestPaidSalary = emp.salary;
                highestPaidName = emp.name;
            }
        });

        const sortedDepts = Object.keys(deptStats).sort();

        const formatCurrency = (num: number, decimals = 0) => {
            // For integers, we round to ensure no decimal part is present
            const value = decimals === 0 ? Math.round(num) : num;
            return value.toLocaleString('en-US', {
                minimumFractionDigits: decimals,
                maximumFractionDigits: decimals
            });
        };

        // Output construction
        process.stdout.write('=== Salary Report ===\n\n');

        process.stdout.write('Average Salary by Department:\n');
        sortedDepts.forEach(dept => {
            const avg = deptStats[dept].sum / deptStats[dept].count;
            process.stdout.write(`  ${dept}: $${formatCurrency(avg, 2)}\n`);
        });

        process.stdout.write('\n');
        process.stdout.write(`Highest Paid: ${highestPaidName} ($${formatCurrency(highestPaidSalary)})\n\n`);

        process.stdout.write('Departments with >2 employees:\n');
        const largeDepts = sortedDepts.filter(dept => deptStats[dept].count > 2);
        largeDepts.forEach(dept => {
            process.stdout.write(`  ${dept} (${deptStats[dept].count} employees)\n`);
        });

        process.stdout.write(`\nTotal Budget: $${formatCurrency(totalBudget)}\n`);

    } catch (error) {
        // Silently fail or handle error as per requirements
    }
}

