import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        TreeMap<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrorCounts = new HashMap<>();
        TreeSet<String> errorMessages = new TreeSet<>();
        int[] hourCounts = new int[24];

        try (BufferedReader br = Files.newBufferedReader(Paths.get(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;

                int closeBracketIdx = line.indexOf(']');
                if (closeBracketIdx == -1) continue;
                String timestamp = line.substring(1, closeBracketIdx);

                String rest = line.substring(closeBracketIdx + 2);
                int firstSpaceIdx = rest.indexOf(' ');
                if (firstSpaceIdx == -1) continue;
                String level = rest.substring(0, firstSpaceIdx);

                String rest2 = rest.substring(firstSpaceIdx + 1);
                int openParenIdx = rest2.indexOf('(');
                int closeParenIdx = rest2.indexOf(')');
                if (openParenIdx == -1 || closeParenIdx == -1) continue;
                String component = rest2.substring(openParenIdx + 1, closeParenIdx);

                int dashIdx = rest2.indexOf(" - ");
                if (dashIdx == -1) continue;
                String message = rest2.substring(dashIdx + 3);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                if ("ERROR".equals(level)) {
                    componentErrorCounts.put(component, componentErrorCounts.getOrDefault(component, 0) + 1);
                    errorMessages.add(message);
                }
                if (timestamp.length() >= 13) {
                    try {
                        int hour = Integer.parseInt(timestamp.substring(11, 13));
                        if (hour >= 0 && hour < 24) {
                            hourCounts[hour]++;
                        }
                    } catch (NumberFormatException e) {
                        // Ignore invalid hour format
                    }
                }
            }
        } catch (IOException e) {
            // Ignore file read errors
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String topComponent = "None";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrorCounts.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                topComponent = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + topComponent + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int busiestHour = 0;
        int maxHourEntries = -1;
        for (int i = 0; i < 24; i++) {
            if (hourCounts[i] > maxHourEntries) {
                maxHourEntries = hourCounts[i];
                busiestHour = i;
            }
        }
        System.out.printf("Busiest Hour: %02d:00 (%d entries)%n", busiestHour, maxHourEntries);
    }
}

