import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try {
            String pathA = "/tmp/…/config_a.json";
            String pathB = "/tmp/…/config_b.json";

            String contentA = new String(Files.readAllBytes(Paths.get(pathA)));
            String contentB = new String(Files.readAllBytes(Paths.get(pathB)));

            JsonParser parserA = new JsonParser(contentA);
            JsonParser parserB = new JsonParser(contentB);

            Object jsonA = parserA.parse();
            Object jsonB = parserB.parse();

            Object merged = merge(jsonA, jsonB);
            System.out.print(serialize(merged, 0));
        } catch (Exception e) {
            // Silent failure as per requirements
        }
    }

    private static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;
            TreeMap<String, Object> result = new TreeMap<>();
            Set<String> allKeys = new TreeSet<>(mapA.keySet());
            allKeys.addAll(mapB.keySet());
            for (String key : allKeys) {
                if (mapA.containsKey(key) && mapB.containsKey(key)) {
                    result.put(key, merge(mapA.get(key), mapB.get(key)));
                } else if (mapB.containsKey(key)) {
                    result.put(key, mapB.get(key));
                } else {
                    result.put(key, mapA.get(key));
                }
            }
            return result;
        } else if (a instanceof List && b instanceof List) {
            List<Object> listA = (List<Object>) a;
            List<Object> listB = (List<Object>) b;
            List<Object> result = new ArrayList<>(listA);
            for (Object itemB : listB) {
                if (!result.contains(itemB)) {
                    result.add(itemB);
                }
            }
            return result;
        } else {
            return b;
        }
    }

    private static String serialize(Object obj, int indent) {
        if (obj instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) obj;
            if (map.isEmpty()) return "{}";
            StringBuilder sb = new StringBuilder("{\n");
            int i = 0;
            for (Map.Entry<String, Object> entry : map.entrySet()) {
                sb.append(" ".repeat(indent + 2))
                  .append("\"").append(entry.getKey()).append("\": ")
                  .append(serialize(entry.getValue(), indent + 2));
                if (++i < map.size()) sb.append(",");
                sb.append("\n");
            }
            sb.append(" ".repeat(indent)).append("}");
            return sb.toString();
        } else if (obj instanceof List) {
            List<?> list = (List<?>) obj;
            if (list.isEmpty()) return "[]";
            StringBuilder sb = new StringBuilder("[\n");
            for (int i = 0; i < list.size(); i++) {
                sb.append(" ".repeat(indent + 2))
                  .append(serialize(list.get(i), indent + 2));
                if (i < list.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(" ".repeat(indent)).append("]");
            return sb.toString();
        } else if (obj instanceof String) {
            String s = (String) obj;
            return "\"" + s.replace("\"", "\\\"") + "\"";
        } else if (obj == null) {
            return "null";
        } else {
            return String.valueOf(obj);
        }
    }

    static class JsonParser {
        private final String input;
        private int pos = 0;

        public JsonParser(String input) {
            this.input = input;
        }

        public Object parse() {
            return parseValue();
        }

        private Object parseValue() {
            skipWhitespace();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            return parsePrimitive();
        }

        private Map<String, Object> parseObject() {
            pos++; // skip {
            TreeMap<String, Object> map = new TreeMap<>();
            skipWhitespace();
            while (pos < input.length() && input.charAt(pos) != '}') {
                String key = parseString();
                skipWhitespace();
                pos++; // skip :
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            pos++; // skip }
            return map;
        }

        private List<Object> parseArray() {
            pos++; // skip [
            List<Object> list = new ArrayList<>();
            skipWhitespace();
            while (pos < input.length() && input.charAt(pos) != ']') {
                list.add(parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            pos++; // skip ]
            return list;
        }

        private String parseString() {
            pos++; // skip "
            StringBuilder sb = new StringBuilder();
            while (pos < input.length() && input.charAt(pos) != '"') {
                char c = input.charAt(pos++);
                if (c == '\\') {
                    if (pos >= input.length()) break;
                    char next = input.charAt(pos++);
                    switch (next) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        default: sb.append(next); break;
                    }
                } else {
                    sb.append(c);
                }
            }
            pos++; // skip "
            return sb.toString();
        }

        private Object parsePrimitive() {
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (Character.isWhitespace(c) || c == ',' || c == '}' || c == ']') break;
                sb.append(c);
                pos++;
            }
            String s = sb.toString();
            if (s.equals("true")) return true;
            if (s.equals("false")) return false;
            if (s.equals("null")) return null;
            try {
                if (s.contains(".") || s.contains("e") || s.contains("E")) return Double.parseDouble(s);
                return Long.parseLong(s);
            } catch (NumberFormatException e) {
                return s;
            }
        }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) {
                pos++;
            }
        }
    }
}

