void format_currency_int(long long value, char *buffer) {
    if (value == 0) {
        strcpy(buffer, "0");
        return;
    }
    char temp[64];
    sprintf(temp, "%lld", value);
    int len = strlen(temp);
    int j = 0;
    for (int i = len - 1; i >= 0; i--) {
        if ((len - 1 - i) > 0 && (len - 1 - i) % 3 == 0) {
            buffer[j++] = ',';
        }
        buffer[j++] = temp[i];
    }
    buffer[j] = '\0';
    for (int i = 0; i < j / 2; i++) {
        char tmp = buffer[i];
        buffer[i] = buffer[j - 1 - i];
        buffer[j - 1 - i] = tmp;
    }
}

void format_currency_float(double value, char *buffer) {
    char temp[64];
    sprintf(temp, "%.2f", value);
    char *dot = strchr(temp, '.');
    if (!dot) {
        format_currency_int((long long)value, buffer);
        strcat(buffer, ".00");
        return;
    }
    int int_len = dot - temp;
    char int_part[64];
    int j = 0;
    for (int i = int_len - 1; i >= 0; i--) {
        if ((int_len - 1 - i) > 0 && (int_len - 1 - i) % 3 == 0) {
            int_part[j++] = ',';
        }
        int_part[j++] = temp[i];
    }
    int_part[j] = '\0';
    for (int i = 0; i < j / 2; i++) {
        char tmp = int_part[i];
        int_part[i] = int_part[j - 1 - i];
        int_part[j - 1 - i] = tmp;
    }
    sprintf(buffer, "%s%s", int_part, dot);
}

char *parse_csv_field(char **line) {
    if (*line == NULL) return NULL;
    char *start = *line;
    char *end = strchr(start, ',');
    if (end) {
        *end = '\0';
        *line = end + 1;
    } else {
        *line = NULL;
    }
    char *newline = strpbrk(start, "\r\n");
    if (newline) *newline = '\0';
    return start;
}

int compare_depts(const void *a, const void *b) {
    return strcmp(((DeptStat *)a)->name, ((DeptStat *)b)->name);
}

int main(void) {
    const char *filename = "/tmp/…/employees.csv";
    FILE *fp = fopen(filename, "r");
    if (!fp) return 1;

    char line[1024];
    if (!fgets(line, sizeof(line), fp)) {
        fclose(fp);
        return 0;
    }

    DeptStat *dept_stats = NULL;
    int dept_count = 0;
    double total_budget = 0;
    double max_salary = -1.0;
    char max_salary_name[128] = "";

    while (fgets(line, sizeof(line), fp)) {
        char line_copy[1024];
        strcpy(line_copy, line);
        char *line_ptr = line_copy;

