        char *name_str = parse_csv_field(&line_ptr);
        char *dept_str = parse_csv_field(&line_ptr);
        char *salary_str = parse_csv_field(&line_ptr);

        if (!name_str || !dept_str || !salary_str) continue;

        double salary = atof(salary_str);
        total_budget += salary;

        if (salary > max_salary) {
            max_salary = salary;
            strncpy(max_salary_name, name_str, sizeof(max_salary_name) - 1);
        }

        int found = 0;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(dept_stats[i].name, dept_str) == 0) {
                dept_stats[i].total_salary += salary;
                dept_stats[i].count++;
