        }

        if (!found) {
            dept_stats = realloc(dept_stats, sizeof(DeptStat) * (dept_count + 1));
            strncpy(dept_stats[dept_count].name, dept_str, sizeof(dept_stats[dept_count].name) - 1);
            dept_stats[dept_count].total_salary = salary;
            dept_stats[dept_count].count = 1;
            dept_count++;
        }
    }
