    qsort(dept_stats, dept_count, sizeof(DeptStat), compare_depts);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_count; i++) {
        char formatted_avg[64];
        format_currency_float(dept_stats[i].total_salary / dept_stats[i].count, formatted_avg);
        printf("  %s: $%s\n", dept_stats[i].name, formatted_avg);
    }

    char max_sal_fmt[64];
    format_currency_int((long long)round(max_salary), max_sal_fmt);
    printf("\nHighest Paid: %s ($%s)\n\n", max_salary_name, max_sal_fmt);

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (dept_stats[i].count > 2) {
            printf("  %s (%d employees)\n", dept_stats[i].name, dept_stats[i].count);
        }
    }

    char total_bud_fmt[64];
    format_currency_int((long long)round(total_budget), total_bud_fmt);
    printf("\nTotal Budget: $%s\n", total_bud_fmt);

    free(dept_stats);
    return 0;
}

