let filePath = "/tmp/…/app.log"
guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

var levelCounts = [String: Int]()
var componentErrorCounts = [String: Int]()
var uniqueErrorMessages = Set<String>()
var hourCounts = [String: Int]()

let lines = content.components(separatedBy: .newlines)
for line in lines {
    let trimmedLine = line.trimmingCharacters(in: .whitespaces)
    if trimmedLine.isEmpty { continue }

    // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
    let parts1 = trimmedLine.split(separator: "]", maxSplits: 1)
    if parts1.count < 2 { continue }

    let timestamp = String(parts1[0].dropFirst())
    let remainder = parts1[1].trimmingCharacters(in: .whitespaces)

    let parts2 = remainder.split(separator: " ")
    if parts2.count < 4 { continue }

    let level = String(parts2[0])
    let component = String(parts2[1].dropFirst().dropLast())
    let message = parts2[3...].joined(separator: " ")

    // Hour extraction
    let timeParts = timestamp.split(separator: " ")
    if timeParts.count >= 2 {
        let hour = String(timeParts[1].split(separator: ":")[0])
        hourCounts[hour, default: 0] += 1
    }

    // Level counting
    levelCounts[level, default: 0] += 1

    // Error analysis
    if level == "ERROR" {
        componentErrorCounts[component, default: 0] += 1
        uniqueErrorMessages.insert(message)
    }
}

