use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    // 1. Make HTTP GET request using standard library TcpStream
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect to server");
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut response = String::new();
    stream.read_to_string(&mut response).expect("Failed to read response");

    // 2. Parse JSON response manually (standard library only)
    // Separate HTTP body from headers
    let body_start = response.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let body = &response[body_start..];

    let mut products = Vec::new();
    let mut current_pos = 0;

    // Find each JSON object within the array
    while let Some(start_bracket) = body[current_pos..].find('{') {
        let start_idx = current_pos + start_bracket;
        let end_bracket = body[start_idx..].find('}').expect("Missing closing brace");
        let object_str = &body[start_idx..start_idx + end_bracket];

        // Extract "name" value
        let name = if let Some(n_key) = object_str.find("\"name\"") {
            let after_key = &object_str[n_key + 7..];
            if let Some(start_quote) = after_key.find('"') {
                let start_quote_idx = start_quote + 1;
                if let Some(end_quote) = after_key[start_quote_idx..].find('"') {
                    after_key[start_quote_idx..start_quote_idx + end_quote].to_string()
                } else {
                    "".to_string()
                }
            } else {
                "".to_string()
            }
        } else {
            "".to_string()
        };

        // Extract "price" value
        let price = if let Some(p_key) = object_str.find("\"price\"") {
            let after_key = &object_str[p_key + 8..];
            if let Some(start_val) = after_key.find(|c: char| c.is_ascii_digit() || c == '-') {
                let remaining = &after_key[start_val..];
                let end_val = remaining.find(|c: char| !c.is_ascii_digit() && c != '.').unwrap_or(remaining.len());
                remaining[..end_val].parse::<f64>().unwrap_or(0.0)
            } else {
                0.0
            }
        } else {
            0.0
        };

        products.push(Product { name, price });
        current_pos = start_idx + end_bracket + 1;
    }

    // 3. Filter products where price > 50.00
    let mut filtered: Vec<Product> = products.into_iter().filter(|p| p.price > 50.0).collect();

    // 4. Sort filtered products by name ascending
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    // 5. Print the output in the exact specified format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total_sum = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total_sum += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total_sum);
}

#include <stdio.h>
