typedef struct {
    char *name;
    int count;
} Entry;

typedef struct {
    char *name;
    int count;
} Component;

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *d = malloc(len);
    if (d) memcpy(d, s, len);
    return d;
}

int compare_entries(const void *a, const void *b) {
    return strcmp(((Entry *)a)->name, ((Entry *)b)->name);
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(void) {
    const char *filename = "/tmp/…/app.log";
    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;

    char *line = malloc(4096);
    Entry *levels = NULL;
    int level_count = 0;
    Component *components = NULL;
    int comp_count = 0;
    char **error_msgs = NULL;
    int msg_count = 0;
    int hour_counts[24] = {0};

    while (fgets(line, 4096, fp)) {
        int hour;
        char level[64], component[64], message[1024];
        if (sscanf(line, "[%*[^ ] %d:%*d:%*d] %s (%[^)]) - %[^\n]", &hour, level, component, message) == 4) {
            if (hour >= 0 && hour < 24) {
                hour_counts[hour]++;
            }

            int found_lvl = 0;
            for (int i = 0; i < level_count; i++) {
                if (strcmp(levels[i].name, level) == 0) {
                    levels[i].count++;
                    found_lvl = 1;
                    break;
                }
            }
            if (!found_lvl) {
                Entry *tmp = realloc(levels, sizeof(Entry) * (level_count + 1));
                if (tmp) {
                    levels = tmp;
                    levels[level_count].name = my_strdup(level);
                    levels[level_count].count = 1;
                    level_count++;
                }
            }

            if (strcmp(level, "ERROR") == 0) {
                int found_comp = 0;
                for (int i = 0; i < comp_count; i++) {
                    if (strcmp(components[i].name, component) == 0) {
                        components[i].count++;
                        found_comp = 1;
                        break;
                    }
                }
                if (!found_comp) {
                    Component *tmp = realloc(components, sizeof(Component) * (comp_count + 1));
                    if (tmp) {
                        components = tmp;
                        components[comp_count].name = my_strdup(component);
                        components[comp_count].count = 1;
                        comp_count++;
                    }
                }

                int found_msg = 0;
                for (int i = 0; i < msg_count; i++) {
                    if (strcmp(error_msgs[i], message) == 0) {
                        found_msg = 1;
                        break;
                    }
                }
                if (!found_msg) {
                    char **tmp = realloc(error_msgs, sizeof(char *) * (msg_count + 1));
                    if (tmp) {
                        error_msgs = tmp;
                        error_msgs[msg_count] = my_strdup(message);
                        msg_count++;
                    }
                }
            }
        }
    }
    fclose(fp);

    qsort(levels, level_count, sizeof(Entry), compare_entries);

    int max_h = 0;
    for (int i = 1; i < 24; i++) {
        if (hour_counts[i] > hour_counts[max_h]) {
            max_h = i;
        }
    }

    int max_err = -1;
    char *best_comp = "None";
    for (int i = 0; i < comp_count; i++) {
        if (components[i].count > max_err) {
            max_err = components[i].count;
            best_comp = components[i].name;
        }
    }
    if (max_err == -1) max_err = 0;

    qsort(error_msgs, msg_count, sizeof(char *), compare_strings);

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < level_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    printf("Component with Most Errors: %s (%d errors)\n\n", best_comp, max_err);
    printf("Unique Error Messages:\n");
    for (int i = 0; i < msg_count; i++) {
        printf("  - %s\n", error_msgs[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", max_h, hour_counts[max_h]);

    for (int i = 0; i < level_count; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < comp_count; i++) free(components[i].name);
    free(components);
    for (int i = 0; i < msg_count; i++) free(error_msgs[i]);
    free(error_msgs);
    free(line);

    return 0;
}

