struct Edge: Codable {
    let from: String
    let to: String
    let weight: Int
}

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

let filePath = "/tmp/…/graph.json"
guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
    exit(1)
}

let decoder = JSONDecoder()
guard let graphData = try? decoder.decode(GraphData.self, from: data) else {
    exit(1)
}

let nodes = graphData.nodes
var adj = [String: [(node: String, weight: Int)]]()
for node in nodes {
    adj[node] = []
}

for edge in graphData.edges {
    adj[edge.from]?.append((edge.to, edge.weight))
    adj[edge.to]?.append((edge.from, edge.weight))
}

var distances = [String: Int]()
for node in nodes {
    distances[node] = Int.max
}

if distances["A"] != nil {
    distances["A"] = 0
}

var unvisited = Set(nodes)

while !unvisited.isEmpty {
    var minNode: String? = nil
    var minDist = Int.max

    for node in unvisited {
        if let d = distances[node], d < minDist {
            minDist = d
            minNode = node
        }
    }

    guard let u = minNode else { break }
    unvisited.remove(u)

    if let neighbors = adj[u] {
        for neighbor in neighbors {
            let v = neighbor.node
            let weight = neighbor.weight
            if let distU = distances[u], let distV = distances[v], distU != Int.max {
                if distU + weight < distV {
                    distances[v] = distU + weight
                }
            }
        }
    }
}

