import json
import heapq

def main():
    file_path = '/tmp/…/graph.json'

    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return

    nodes = data.get('nodes', [])
    edges = data.get('edges', [])

    # Build adjacency list for an undirected graph
    adj = {node: [] for node in nodes}
    for edge in edges:
        u, v, w = edge['from'], edge['to'], edge['weight']
        if u in adj and v in adj:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in nodes}
    if 'A' in distances:
        distances['A'] = 0
        pq = [(0, 'A')]

        while pq:
            curr_dist, curr_node = heapq.heappop(pq)

            if curr_dist > distances[curr_node]:
                continue

            for neighbor, weight in adj[curr_node]:
                distance = curr_dist + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))

    # Output formatting
    print("=== Shortest Paths from A ===\n")
    for node in sorted(nodes):
        d = distances[node]
        if d == float('inf'):
            print(f"A -> {node}: inf")
        else:
            # Print as integer if distance is a whole number
            print(f"A -> {node}: {int(d) if d == int(d) else d}")

if __name__ == "__main__":
    main()

