    char *response = malloc(1024 * 1024);
    if (!response) {
        close(sock);
        return 1;
    }

    int total_received = 0;
    int n;
    while ((n = recv(sock, response + total_received, 1024 * 1024 - total_received - 1, 0)) > 0) {
        total_received += n;
    }
    response[total_received] = '\0';
    close(sock);

    char *json_start = strstr(response, "\r\n\r\n");
