    while ((ptr = strchr(ptr, '{')) != NULL) {
        struct Product p = {0};
        char *end_of_obj = strchr(ptr, '}');
        if (!end_of_obj) break;

        char *search_ptr = ptr;
        while (search_ptr < end_of_obj) {
            char *key_start = strchr(search_ptr, '\"');
            if (!key_start || key_start > end_of_obj) break;
            char *key_end = strchr(key_start + 1, '\"');
            if (!key_end || key_end > end_of_obj) break;

            int key_len = key_end - (key_start + 1);
            char key[64] = {0};
            if (key_len < 63) memcpy(key, key_start + 1, key_len);

            char *colon = strchr(key_end, ':');
            if (!colon || colon > end_of_obj) break;

            char *val_start = colon + 1;
            while (*val_start == ' ' || *val_start == '\t' || *val_start == '\n' || *val_start == '\r') {
                val_start++;
            }

            if (strcmp(key, "name") == 0) {
                if (*val_start == '\"') {
                    val_start++;
                    char *val_end = strchr(val_start, '\"');
                    if (val_end && val_end < end_of_obj) {
                        int vlen = val_end - val_start;
                        if (vlen < 255) {
                            memcpy(p.name, val_start, vlen);
                            p.name[vlen] = '\0';
                        }
                    }
                }
            } else if (strcmp(key, "price") == 0) {
                p.price = atof(val_start);
            }
            search_ptr = key_end + 1;
        }

        if (p.price > 50.00) {
            filtered[filtered_count++] = p;
        }
        ptr = end_of_obj + 1;
    }

    qsort(filtered, filtered_count, sizeof(struct Product), compare_products);

    double total_sum = 0;
    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < filtered_count; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
        total_sum += filtered[i].price;
    }

    printf("\nCount: %d\nTotal: $%.2f\n", filtered_count, total_sum);

    free(response);
    free(filtered);
    return 0;
}

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://127.0.0.1:18923/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                response.append(line);
            }
            in.close();
            conn.disconnect();

            String json = response.toString();
            List<Product> products = new ArrayList<>();

            // Regex to identify individual JSON objects within the array
            Pattern objectPattern = Pattern.compile("\\{[^\\}]*\\}");
            Matcher objectMatcher = objectPattern.matcher(json);

            while (objectMatcher.find()) {
                String obj = objectMatcher.group();
                String name = extractValue(obj, "name");
                String priceStr = extractValue(obj, "price");
                if (name != null && priceStr != null) {
                    try {
                        products.add(new Product(name, Double.parseDouble(priceStr)));
                    } catch (NumberFormatException e) {
                        // Skip malformed price
                    }
                }
            }

            // Filter products where price > 50.00
            List<Product> filtered = new ArrayList<>();
            double total = 0;
            for (Product p : products) {
                if (p.price > 50.00) {
                    filtered.add(p);
                    total += p.price;
                }
            }

            // Sort filtered products by name ascending
            Collections.sort(filtered, (p1, p2) -> p1.name.compareTo(p2.name));

            // Print formatted output
            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();
            for (Product p : filtered) {
                System.out.printf(Locale.US, "%s: $%.2f%n", p.name, p.price);
            }
            System.out.println();
            System.out.println("Count: " + filtered.size());
            System.out.printf(Locale.US, "Total: $%.2f%n", total);

        } catch (Exception e) {
            // Silent fail as per constraints
        }
    }

    private static String extractValue(String json, String key) {
        // Regex to handle both quoted strings and numeric values
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*(\"([^\"]*)\"|([0-9.]+))");
        Matcher m = p.matcher(json);
        if (m.find()) {
            if (m.group(2) != null) return m.group(2); // Quoted string
            if (m.group(3) != null) return m.group(3); // Number
        }
        return null;
    }
}

use std::collections::{BTreeSet, HashMap};
use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let file_path = "/tmp/…/app.log";
    let file = match File::open(file_path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts = [0usize; 24];

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.is_empty() {
            continue;
        }

        if let Some(close_bracket_idx) = line.find(']') {
            let timestamp = &line[1..close_bracket_idx];
            let remainder = if line.len() > close_bracket_idx + 2 {
                &line[close_bracket_idx + 2..]
            } else {
                ""
            };

            if let Some(space_idx) = timestamp.find(' ') {
                let time_part = &timestamp[space_idx + 1..];
                if time_part.len() >= 2 {
                    if let Ok(hour) = time_part[0..2].parse::<usize>() {
                        if hour < 24 {
                            hour_counts[hour] += 1;
                        }
                    }
                }
            }

            if let Some(level_end_idx) = remainder.find(' ') {
                let level = &remainder[0..level_end_idx];
                let after_level = &remainder[level_end_idx + 1..];

                *level_counts.entry(level.to_string()).or_insert(0) += 1;

                if level == "ERROR" {
                    if let Some(comp_start_idx) = after_level.find('(') {
                        if let Some(comp_end_idx) = after_level.find(')') {
                            let component = &after_level[comp_start_idx + 1..comp_end_idx];
                            *component_errors.entry(component.to_string()).or_insert(0) += 1;

                            if let Some(msg_start_idx) = after_level.find(" - ") {
                                let message = &after_level[msg_start_idx + 3..];
                                error_messages.insert(message.to_string());
                            }
                        }
                    }
                }
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut sorted_levels: Vec<_> = level_counts.keys().collect();
    sorted_levels.sort();
    for level in sorted_levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let max_comp = component_errors.iter().max_by_key(|entry| entry.1);
    match max_comp {
        Some((comp, count)) => println!("Component with Most Errors: {} ({} errors)", comp, count),
        None => println!("Component with Most Errors: None (0 errors)"),
    }
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let mut busiest_hour = 0;
    let mut max_hour_count = 0;
    for (hour, &count) in hour_counts.iter().enumerate() {
        if count > max_hour_count {
            max_hour_count = count;
            busiest_hour = hour;
        }
    }
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, max_hour_count);
}

