func formatValue(_ value: Any, indent: String, nextIndent: String) -> String {
    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        var lines = [String]()
        for key in sortedKeys {
            let val = dict[key]!
            lines.append("\(indent)\"\(key)\": \(formatValue(val, indent: nextIndent, nextIndent: nextIndent + "  "))")
        }
        if lines.isEmpty { return "{}" }
        return "{\n" + lines.joined(separator: ",\n") + "\n\(indent)}"
    } else if let array = value as? [Any] {
        if array.isEmpty { return "[]" }
        var lines = [String]()
        for item in array {
            lines.append("\(nextIndent)\(formatValue(item, indent: nextIndent + "  ", nextIndent: nextIndent + "  "))")
        }
        return "[\n" + lines.joined(separator: ",\n") + "\n\(indent)]"
    } else if let str = value as? String {
        let escaped = str.replacingOccurrences(of: "\\", with: "\\\\")
                        .replacingOccurrences(of: "\"", with: "\\\"")
        return "\"\(escaped)\""
    } else if let bool = value as? Bool {
        return bool ? "true" : "false"
    } else if let num = value as? NSNumber {
        if let doubleVal = num.doubleValue as Double?, doubleVal == floor(doubleVal) {
            return "\(Int(doubleVal))"
        }
        return "\(num)"
    }
    return "null"
}

