import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/graph.json";
        try {
            String content = Files.readString(Path.of(filePath));

            // Parse nodes
            int nodesStart = content.indexOf("\"nodes\":");
            int nodesOpenBracket = content.indexOf("[", nodesStart);
            int nodesCloseBracket = content.indexOf("]", nodesOpenBracket);
            String nodesPart = content.substring(nodesOpenBracket + 1, nodesCloseBracket);

            List<String> nodes = new ArrayList<>();
            Pattern nodePattern = Pattern.compile("\"([^\"]+)\"");
            Matcher nodeMatcher = nodePattern.matcher(nodesPart);
            while (nodeMatcher.find()) {
                nodes.add(nodeMatcher.group(1));
            }

            // Parse edges
            int edgesStart = content.indexOf("\"edges\":");
            int edgesOpenBracket = content.indexOf("[", edgesStart);
            int edgesCloseBracket = content.lastIndexOf("]");
            String edgesPart = content.substring(edgesOpenBracket + 1, edgesCloseBracket);

            Map<String, List<Edge>> adjList = new HashMap<>();
            Pattern objectPattern = Pattern.compile("\\{[^}]*\\}");
            Matcher objectMatcher = objectPattern.matcher(edgesPart);
            while (objectMatcher.find()) {
                String obj = objectMatcher.group();
                String from = extractValue(obj, "from");
                String to = extractValue(obj, "to");
                int weight = Integer.parseInt(extractValue(obj, "weight"));

                adjList.computeIfAbsent(from, k -> new ArrayList<>()).add(new Edge(to, weight));
                adjList.computeIfAbsent(to, k -> new ArrayList<>()).add(new Edge(from, weight));
            }

            // Dijkstra's Algorithm
            Map<String, Integer> dist = new HashMap<>();
            for (String node : nodes) {
                dist.put(node, Integer.MAX_VALUE);
            }

            String startNode = "A";
            if (dist.containsKey(startNode)) {
                dist.put(startNode, 0);
                PriorityQueue<NodeDistance> pq = new PriorityQueue<>();
                pq.add(new NodeDistance(startNode, 0));

                while (!pq.isEmpty()) {
                    NodeDistance current = pq.poll();
                    String u = current.node;
                    int d = current.distance;

                    if (d > dist.get(u)) continue;

                    for (Edge edge : adjList.getOrDefault(u, new ArrayList<>())) {
                        if (dist.get(u) != Integer.MAX_VALUE && dist.get(u) + edge.weight < dist.get(edge.to)) {
                            dist.put(edge.to, dist.get(u) + edge.weight);
                            pq.add(new NodeDistance(edge.to, dist.get(edge.to)));
                        }
                    }
                }
            }

            // Output results
            Collections.sort(nodes);
            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            for (String node : nodes) {
                System.out.println("A -> " + node + ": " + dist.get(node));
            }

        } catch (IOException e) {
            // Handle exception if needed
        }
    }

    private static String extractValue(String obj, String key) {
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*(\"([^\"]+)\"|(\\d+))");
        Matcher m = p.matcher(obj);
        if (m.find()) {
            if (m.group(2) != null) return m.group(2);
            return m.group(3);
        }
        return "";
    }

    static class Edge {
        String to;
        int weight;
        Edge(String to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class NodeDistance implements Comparable<NodeDistance> {
        String node;
        int distance;
        NodeDistance(String node, int distance) {
            this.node = node;
            this.distance = distance;
        }
        @Override
        public int compareTo(NodeDistance other) {
            return Integer.compare(this.distance, other.distance);
        }
    }
}

