char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (fp == NULL) {
        return NULL;
    }

    char *buffer = malloc(1024);
    if (buffer == NULL) {
        pclose(fp);
        return NULL;
    }

    if (fgets(buffer, 1024, fp) != NULL) {
        size_t len = strlen(buffer);
        while (len > 0 && isspace((unsigned char)buffer[len - 1])) {
            buffer[len - 1] = '\0';
            len--;
        }
    }

    pclose(fp);
    return buffer;
