import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileInfo implements Comparable<FileInfo> {
        String path;
        long lines;
        long bytes;

        FileInfo(String path, long lines, long bytes) {
            this.path = path;
            this.lines = lines;
            this.bytes = bytes;
        }

        @Override
        public int compareTo(FileInfo other) {
            return this.path.compareTo(other.path);
        }
    }

    public static void main(String[] args) {
        Path root = Paths.get("/tmp/…/project_tree");
        TreeMap<String, List<FileInfo>> groups = new TreeMap<>();

        try {
            Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    String fileName = file.getFileName().toString();
                    int dotIdx = fileName.lastIndexOf('.');
                    String ext = (dotIdx == -1) ? "" : fileName.substring(dotIdx);

                    String relPath = root.relativize(file).toString().replace('\\', '/');
                    long lines = countLines(file);
                    long bytes = attrs.size();

                    groups.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, bytes));
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            // Ignore errors during directory walking
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalBytes = 0;

        for (Map.Entry<String, List<FileInfo>> entry : groups.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();
            Collections.sort(files);

            long extLines = 0;
            long extBytes = 0;
            for (FileInfo f : files) {
                extLines += f.lines;
                extBytes += f.bytes;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extBytes);
            for (FileInfo f : files) {
                System.out.println("    " + f.path + ": " + f.lines + " lines, " + f.bytes + " chars");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalBytes += extBytes;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalBytes + " characters");
    }

    private static long countLines(Path path) {
        long count = 0;
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            while (reader.readLine() != null) {
                count++;
            }
        } catch (IOException e) {
            // Ignore errors during file reading
        }
        return count;
    }
}

