import * as fs from 'fs';
import * as path from 'path';

const baseDir = '/tmp/…/project_tree';

interface FileInfo {
    path: string;
    lines: number;
    chars: number;
}

interface ExtInfo {
    files: FileInfo[];
    totalLines: number;
    totalChars: number;
}

const extensionsMap = new Map<string, ExtInfo>();

function walk(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            walk(fullPath);
        } else if (entry.isFile()) {
            const ext = path.extname(entry.name);
            const stats = fs.statSync(fullPath);
            const size = stats.size;

            // Read as utf8 to count lines, but use stat size for total bytes
            const content = fs.readFileSync(fullPath, 'utf8');

            let lines = content.split(/\r?\n/).length;
            if (content.endsWith('\n')) {
                lines--;
            }
            if (content === '') {
                lines = 0;
            }

            const relPath = path.relative(baseDir, fullPath).replace(/\\/g, '/');

            if (!extensionsMap.has(ext)) {
                extensionsMap.set(ext, { files: [], totalLines: 0, totalChars: 0 });
            }
            const extInfo = extensionsMap.get(ext)!;
            extInfo.files.push({ path: relPath, lines, chars: size });
            extInfo.totalLines += lines;
            extInfo.totalChars += size;
        }
    }
}

try {
    walk(baseDir);

    process.stdout.write('=== File Tree Analysis ===\n\n');

    const sortedExts = Array.from(extensionsMap.keys()).sort();
    let totalFiles = 0;
    let totalLines = 0;
    let totalChars = 0;

    for (const ext of sortedExts) {
        const info = extensionsMap.get(ext)!;
        const sortedFiles = info.files.sort((a, b) => a.path.localeCompare(b.path));

        process.stdout.write(`Extension: ${ext}\n`);
        process.stdout.write(`  Files: ${sortedFiles.length}\n`);
        process.stdout.write(`  Total Lines: ${info.totalLines}\n`);
        process.stdout.write(`  Total Characters: ${info.totalChars}\n`);

        for (const file of sortedFiles) {
            process.stdout.write(`    ${file.path}: ${file.lines} lines, ${file.chars} chars\n`);
        }

        totalFiles += sortedFiles.length;
        totalLines += info.totalLines;
        totalChars += info.totalChars;
    }

    process.stdout.write(`\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`);
} catch (err) {
    // Silently handle errors as per requirements to run to completion
}

