        json_value *val = parse_value(p);
        v->object.pairs = realloc(v->object.pairs, sizeof(json_kv) * (v->object.count + 1));
        v->object.pairs[v->object.count].key = key;
        v->object.pairs[v->object.count].val = val;
        v->object.count++;
        skip_ws(p);
        if (**p == ',') { (*p)++; skip_ws(p); }
    }
    if (**p) (*p)++;
    return v;
}

json_value* parse_array(const char **p) {
    (*p)++;
    json_value *v = calloc(1, sizeof(json_value));
    v->type = JSON_ARRAY;
    skip_ws(p);
    while (**p && **p != ']') {
        json_value *val = parse_value(p);
        v->array.elements = realloc(v->array.elements, sizeof(json_value*) * (v->array.count + 1));
        v->array.elements[v->array.count++] = val;
        skip_ws(p);
        if (**p == ',') { (*p)++; skip_ws(p); }
    }
    if (**p) (*p)++;
    return v;
}

json_value* parse_value(const char **p) {
    skip_ws(p);
    if (**p == '{') return parse_object(p);
    if (**p == '[') return parse_array(p);
    if (**p == '\"') {
        char *s = parse_string(p);
        json_value *v = calloc(1, sizeof(json_value));
        v->type = JSON_STRING; v->s = s; return v;
    }
    if (strncmp(*p, "true", 4) == 0 && (!(*p)[4] || !isalnum((*p)[4]))) { *p += 4; json_value *v = calloc(1, sizeof(json_value)); v->type = JSON_BOOL; v->b = true; return v; }
    if (strncmp(*p, "false", 5) == 0 && (!(*p)[5] || !isalnum((*p)[5]))) { *p += 5; json_value *v = calloc(1, sizeof(json_value)); v->type = JSON_BOOL; v->b = false; return v; }
    if (strncmp(*p, "null", 4) == 0 && (!(*p)[4] || !isalnum((*p)[4]))) { *p += 4; json_value *v = calloc(1, sizeof(json_value)); v->type = JSON_NULL; return v; }
    char *end;
    double n = strtod(*p, &end);
    *p = end;
    json_value *v = calloc(1, sizeof(json_value));
    v->type = JSON_NUMBER; v->n = n; return v;
}

json_value* json_merge(json_value *a, json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *res = calloc(1, sizeof(json_value));
        res->type = JSON_OBJECT;
        for (size_t i = 0; i < a->object.count; i++) {
            res->object.pairs = realloc(res->object.pairs, sizeof(json_kv) * (res->object.count + 1));
            res->object.pairs[res->object.count].key = strdup(a->object.pairs[i].key);
            res->object.pairs[res->object.count].val = json_copy(a->object.pairs[i].val);
            res->object.count++;
        }
        for (size_t i = 0; i < b->object.count; i++) {
            bool found = false;
            for (size_t j = 0; j < res->object.count; j++) {
                if (strcmp(res->object.pairs[j].key, b->object.pairs[i].key) == 0) {
                    json_value *merged = json_merge(res->object.pairs[j].val, b->object.pairs[i].val);
                    json_free(res->object.pairs[j].val);
                    res->object.pairs[j].val = merged;
                    found = true; break;
                }
            }
            if (!found) {
                res->object.pairs = realloc(res->object.pairs, sizeof(json_kv) * (res->object.count + 1));
                res->object.pairs[res->object.count].key = strdup(b->object.pairs[i].key);
                res->object.pairs[res->object.count].val = json_copy(b->object.pairs[i].val);
                res->object.count++;
            }
        }
        return res;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *res = calloc(1, sizeof(json_value));
        res->type = JSON_ARRAY;
        for (size_t i = 0; i < a->array.count; i++) {
            bool exists = false;
            for (size_t j = 0; j < res->array.count; j++) {
                if (json_equals(res->array.elements[j], a->array.elements[i])) { exists = true; break; }
            }
            if (!exists) {
                res->array.elements = realloc(res->array.elements, sizeof(json_value*) * (res->array.count + 1));
                res->array.elements[res->array.count++] = json_copy(a->array.elements[i]);
            }
        }
        for (size_t i = 0; i < b->array.count; i++) {
            bool exists = false;
            for (size_t j = 0; j < res->array.count; j++) {
                if (json_equals(res->array.elements[j], b->array.elements[i])) { exists = true; break; }
            }
            if (!exists) {
                res->array.elements = realloc(res->array.elements, sizeof(json_value*) * (res->array.count + 1));
                res->array.elements[res->array.count++] = json_copy(b->array.elements[i]);
            }
        }
        return res;
    }
    return json_copy(b);
}

int compare_kv(const void *a, const void *b) {
    return strcmp(((json_kv *)a)->key, ((json_kv *)b)->key);
}

void json_print(json_value *v, int indent) {
    if (v->type == JSON_NULL) printf("null");
    else if (v->type == JSON_BOOL) printf("%s", v->b ? "true" : "false");
    else if (v->type == JSON_NUMBER) printf("%.15g", v->n);
    else if (v->type == JSON_STRING) {
        printf("\"");
        for (char *p = v->s; *p; p++) {
            if (*p == '\"' || *p == '\\') printf("\\");
            printf("%c", *p);
        }
        printf("\"");
    } else if (v->type == JSON_ARRAY) {
        if (v->array.count == 0) printf("[]");
        else {
            printf("[\n");
            for (size_t i = 0; i < v->array.count; i++) {
                for (int j = 0; j < indent + 2; j++) printf(" ");
                json_print(v->array.elements[i], indent + 2);
                if (i < v->array.count - 1) printf(",");
                printf("\n");
            }
            for (int j = 0; j < indent; j++) printf(" ");
            printf("]");
        }
    } else if (v->type == JSON_OBJECT) {
        if (v->object.count == 0) printf("{}");
        else {
            qsort(v->object.pairs, v->object.count, sizeof(json_kv), compare_kv);
            printf("{\n");
            for (size_t i = 0; i < v->object.count; i++) {
                for (int j = 0; j < indent + 2; j++) printf(" ");
                printf("\"%s\": ", v->object.pairs[i].key);
                json_print(v->object.pairs[i].val, indent + 2);
                if (i < v->object.count - 1) printf(",");
                printf("\n");
            }
            for (int j = 0; j < indent; j++) printf(" ");
            printf("}");
        }
    }
}

char* read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    return buf;
}

int main(void) {
    char *content_a = read_file("/tmp/…/config_a.json");
    char *content_b = read_file("/tmp/…/config_b.json");
    if (!content_a || !content_b) return 1;
    const char *p_a = content_a, *p_b = content_b;
    json_value *val_a = parse_value(&p_a);
    json_value *val_b = parse_value(&p_b);
    json_value *merged = json_merge(val_a, val_b);
    json_print(merged, 0);
    printf("\n");
    json_free(val_a); json_free(val_b); json_free(merged);
    free(content_a); free(content_b);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char *rel_path;
    char *ext;
    long lines;
    long chars;
} FileInfo;

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *d = malloc(len);
    if (d) memcpy(d, s, len);
    return d;
}

long count_lines(const char *path) {
    FILE *fp = fopen(path, "rb");
    if (!fp) return 0;
    long lines = 0;
    char buffer[8192];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        for (size_t i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') lines++;
        }
    }
    fclose(fp);
    return lines;
}

void walk(const char *base_path, const char *current_path, FileInfo **files, int *count, int *capacity) {
    DIR *dir = opendir(current_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char full_path[4096];
        snprintf(full_path, sizeof(full_path), "%s/%s", current_path, entry->d_name);

        struct stat st;
        if (lstat(full_path, &st) == -1) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(base_path, full_path, files, count, capacity);
        } else if (S_ISREG(st.st_mode)) {
            if (*count >= *capacity) {
                *capacity *= 2;
                *files = realloc(*files, sizeof(FileInfo) * (*capacity));
            }

            char *dot = strrchr(entry->d_name, '.');
            char *ext = (dot && dot != entry->d_name) ? dot : "";

            size_t root_len = strlen(base_path);
            const char *rel_start = (base_path[root_len - 1] == '/') ? (full_path + root_len) : (full_path + root_len + 1);

            (*files)[*count].rel_path = my_strdup(rel_start);
            (*files)[*count].ext = my_strdup(ext);
            (*files)[*count].chars = st.st_size;
            (*files)[*count].lines = count_lines(full_path);
            (*count)++;
        }
    }
    closedir(dir);
}

int compare_files(const void *a, const void *b) {
    FileInfo *fa = (FileInfo *)a;
    FileInfo *fb = (FileInfo *)b;
    int ext_cmp = strcmp(fa->ext, fb->ext);
    if (ext_cmp != 0) return ext_cmp;
    return strcmp(fa->rel_path, fb->rel_path);
}

int main(void) {
    const char *root_path = "/tmp/…/project_tree";
    int capacity = 100;
    int count = 0;
    FileInfo *files = malloc(sizeof(FileInfo) * capacity);

    walk(root_path, root_path, &files, &count, &capacity);

    qsort(files, count, sizeof(FileInfo), compare_files);

    printf("=== File Tree Analysis ===\n\n");

    long grand_total_lines = 0;
    long grand_total_chars = 0;

    int i = 0;
    while (i < count) {
        int j = i;
        long group_lines = 0;
        long group_chars = 0;
        while (j < count && strcmp(files[i].ext, files[j].ext) == 0) {
            group_lines += files[j].lines;
            group_chars += files[j].chars;
            j++;
        }

        printf("Extension: %s\n", files[i].ext);
        printf("  Files: %d\n", j - i);
        printf("  Total Lines: %ld\n", group_lines);
        printf("  Total Characters: %ld\n", group_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", files[k].rel_path, files[k].lines, files[k].chars);
        }

        grand_total_lines += group_lines;
        grand_total_chars += group_chars;
        i = j;
    }

    printf("\nTotal: %d files, %ld lines, %ld characters\n", count, grand_total_lines, grand_total_chars);

    for (int k = 0; k < count; k++) {
        free(files[k].rel_path);
        free(files[k].ext);
    }
    free(files);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int A[3][3] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };
    int B[3][3] = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };
    int C[3][3];

    // Compute C = A x B
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // Compute determinant of C
    // det(C) = C[0][0]*(C[1][1]*C[2][2] - C[1][2]*C[2][1]) 
    //          - C[0][1]*(C[1][0]*C[2][2] - C[1][2]*C[2][0]) 
    //          + C[0][2]*(C[1][0]*C[2][1] - C[1][1]*C[2][0])
    long long det = (long long)C[0][0] * ((long long)C[1][1] * C[2][2] - (long long)C[1][2] * C[2][1])
                  - (long long)C[0][1] * ((long long)C[1][0] * C[2][2] - (long long)C[1][2] * C[2][0])
                  + (long long)C[0][2] * ((long long)C[1][0] * C[2][1] - (long long)C[1][1] * C[2][0]);

    printf("=== Matrix Operations ===\n\n");

    printf("Matrix A:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", A[i][0], A[i][1], A[i][2]);
    }

    printf("\nMatrix B:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", B[i][0], B[i][1], B[i][2]);
    }

    printf("\nA x B =\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", C[i][0], C[i][1], C[i][2]);
    }

    printf("\nDeterminant: %lld\n", det);

    return 0;
}

function multiply(A: number[][], B: number[][]): number[][] {
    const rowsA = A.length;
    const colsA = A[0].length;
    const colsB = B[0].length;
    const C: number[][] = Array.from({ length: rowsA }, () => Array(colsB).fill(0));

    for (let i = 0; i < rowsA; i++) {
        for (let j = 0; j < colsB; j++) {
            for (let k = 0; k < colsA; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];

    let det = 0;
    for (let j = 0; j < n; j++) {
        const submatrix: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) {
                    row.push(M[i][k]);
                }
            }
            submatrix.push(row);
        }
        const sign = j % 2 === 0 ? 1 : -1;
        det += sign * M[0][j] * determinant(submatrix);
    }
    return det;
}

function formatMatrix(M: number[][]): string {
    return M.map(row => {
        return "  " + row.map(v => v.toString().padStart(4, ' ')).join(' ');
    }).join('\n');
}

function main() {
    const A = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ];

    const B = [
        [9, 8, 7],
        [6, 5, 4],
        [3, 2, 1]
    ];

    const C = multiply(A, B);
    const detC = determinant(C);

    process.stdout.write("=== Matrix Operations ===\n\n");
    process.stdout.write("Matrix A:\n");
    process.stdout.write(formatMatrix(A) + "\n\n");
    process.stdout.write("Matrix B:\n");
    process.stdout.write(formatMatrix(B) + "\n\n");
    process.stdout.write("A x B =\n");
    process.stdout.write(formatMatrix(C) + "\n\n");
    process.stdout.write(`Determinant: ${detC}\n`);
}

main();

