use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

struct FileStats {
    rel_path: String,
    lines: usize,
    bytes: u64,
}

fn main() {
    let root_path = "/tmp/…/project_tree";
    let root = Path::new(root_path);
    let mut extension_map: BTreeMap<String, Vec<FileStats>> = BTreeMap::new();

    walk(root, root, &mut extension_map);

    println!("=== File Tree Analysis ===\n");

    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_bytes = 0;

    for (ext, mut files) in extension_map {
        files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));

        let mut ext_files = 0;
        let mut ext_lines = 0;
        let mut ext_bytes = 0;

        for f in &files {
            ext_files += 1;
            ext_lines += f.lines;
            ext_bytes += f.bytes;
        }

        let ext_display = if ext.is_empty() {
            "".to_string()
        } else {
            format!(".{}", ext)
        };

        println!("Extension: {}", ext_display);
        println!("  Files: {}", ext_files);
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_bytes);

        for f in files {
            println!("    {}: {} lines, {} chars", f.rel_path, f.lines, f.bytes);
        }

        total_files += ext_files;
        total_lines += ext_lines;
        total_bytes += ext_bytes;
    }

    println!("\nTotal: {} files, {} lines, {} characters", total_files, total_lines, total_bytes);
}

fn walk(dir: &Path, base: &Path, map: &mut BTreeMap<String, Vec<FileStats>>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if let Ok(meta) = fs::symlink_metadata(&path) {
                if meta.is_dir() {
                    walk(&path, base, map);
                } else if meta.is_file() {
                    let extension = path
                        .extension()
                        .and_then(|s| s.to_str())
                        .unwrap_or("")
                        .to_string();

                    let rel_path = path
                        .strip_prefix(base)
                        .and_then(|p| p.to_str())
                        .unwrap_or("")
                        .to_string();

                    let bytes = fs::metadata(&path).map(|m| m.len()).unwrap_or(0);
                    let lines = count_lines(&path);

                    map.entry(extension).or_default().push(FileStats {
                        rel_path,
                        lines,
                        bytes,
                    });
                }
            }
        }
    }
}

fn count_lines(path: &Path) -> usize {
    let mut lines = 0;
    let mut last_was_newline = true;
    if let Ok(mut file) = fs::File::open(path) {
        let mut buffer = [0; 8192];
        while let Ok(n) = file.read(&mut buffer) {
            if n == 0 {
                break;
            }
            for &b in &buffer[..n] {
                if b == b'\n' {
                    lines += 1;
                    last_was_newline = true;
                } else {
                    last_was_newline = false;
                }
            }
        }
        if !last_was_newline {
            lines += 1;
        }
    }
    lines
}

