public class Main {
    public static void main(String[] args) {
        int[][] A = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[][] B = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int[][] C = multiply(A, B);
        int detC = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + detC);
    }

    public static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int m = B[0].length;
        int p = A[0].length;
        int[][] result = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < p; k++) {
                    result[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        return result;
    }

    public static int determinant(int[][] m) {
        int n = m.length;
        if (n == 1) return m[0][0];
        if (n == 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];
        int det = 0;
        for (int j = 0; j < n; j++) {
            int sign = (j % 2 == 0) ? 1 : -1;
            det += sign * m[0][j] * determinant(getSubmatrix(m, 0, j));
        }
        return det;
    }

    public static int[][] getSubmatrix(int[][] m, int row, int col) {
        int n = m.length;
        int[][] sub = new int[n - 1][n - 1];
        int r = 0;
        for (int i = 0; i < n; i++) {
            if (i == row) continue;
            int c = 0;
            for (int j = 0; j < n; j++) {
                if (j == col) continue;
                sub[r][c] = m[i][j];
                c++;
            }
            r++;
        }
        return sub;
    }

    public static void printMatrix(int[][] m) {
        for (int[] row : m) {
            System.out.print("  ");
            for (int j = 0; j < row.length; j++) {
                System.out.printf("%4d", row[j]);
                if (j < row.length - 1) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

