            let after_start = &content[nodes_pos + start..];
            if let Some(end) = after_start.find(']') {
                let nodes_part = &after_start[1..end];
                for n in nodes_part.split(',') {
                    let trimmed = n.trim().trim_matches('"');
                    if !trimmed.is_empty() {
                        nodes.push(trimmed.to_string());
                    }
                }
            }
        }
    }

    if let Some(edges_pos) = content.find("\"edges\"") {
        if let Some(start) = content[edges_pos..].find('[') {
            let after_start = &content[edges_pos + start..];
            if let Some(end) = after_start.find(']') {
                let edges_part = &after_start[1..end];
                for edge_str in edges_part.split('}') {
                    let trimmed = edge_str.trim();
                    if trimmed.is_empty() {
                        continue;
                    }
                    let clean = trimmed.trim_start_matches(',').trim_start_matches('{');
                    let mut from = String::new();
                    let mut to = String::new();
                    let mut weight = 0;
                    for pair in clean.split(',') {
                        let kv: Vec<&str> = pair.split(':').collect();
                        if kv.len() < 2 {
                            continue;
                        }
                        let k = kv[0].trim().trim_matches('"');
                        let v = kv[1].trim().trim_matches('"');
                        match k {
                            "from" => from = v.to_string(),
                            "to" => to = v.to_string(),
                            "weight" => weight = v.parse().unwrap_or(0),
                            _ => {}
                        }
                    }
                    if !from.is_empty() {
                        edges.push((from, to, weight));
                    }
                }
            }
        }
    }
    (nodes, edges)
}

