import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function main() {
    const filePath = '/tmp/…/graph.json';
    let data: GraphData;
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        data = JSON.parse(content);
    } catch (e) {
        return;
    }

    const adj = new Map<string, {node: string, weight: number}[]>();
    for (const node of data.nodes) {
        adj.set(node, []);
    }
    for (const edge of data.edges) {
        if (adj.has(edge.from)) {
            adj.get(edge.from)!.push({node: edge.to, weight: edge.weight});
        }
        if (adj.has(edge.to)) {
            adj.get(edge.to)!.push({node: edge.from, weight: edge.weight});
        }
    }

    const distances = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of data.nodes) {
        distances.set(node, Infinity);
    }

    if (distances.has('A')) {
        distances.set('A', 0);
    }

    for (let i = 0; i < data.nodes.length; i++) {
        let u: string | null = null;
        let minD = Infinity;

        for (const node of data.nodes) {
            if (!visited.has(node)) {
                const d = distances.get(node)!;
                if (d < minD) {
                    minD = d;
                    u = node;
                }
            }
        }

        if (u === null || minD === Infinity) break;
        visited.add(u);

        const neighbors = adj.get(u) || [];
        for (const neighbor of neighbors) {
            const alt = distances.get(u)! + neighbor.weight;
            if (alt < (distances.get(neighbor.node) || Infinity)) {
                distances.set(neighbor.node, alt);
            }
        }
    }

    process.stdout.write("=== Shortest Paths from A ===\n\n");
    const sortedNodes = [...data.nodes].sort();
    for (const node of sortedNodes) {
        process.stdout.write(`A -> ${node}: ${distances.get(node)}\n`);
    }
}

